import type { Pathway } from "@/data";

export type PathwayCollection =
  | "One God and divine identity"
  | "Jesus Christ and the incarnation"
  | "Salvation and new birth"
  | "Questions and biblical interpretation";

export type WebsitePathway = Pathway & { collection: PathwayCollection };

function pathway(input: Omit<WebsitePathway, "appSlug"> & { appSlug?: string }): WebsitePathway {
  return { ...input, appSlug: input.appSlug ?? input.slug };
}

export const allPathways: WebsitePathway[] = [
  pathway({ slug: "god-is-one", title: "God Is One", summary: "Begin with Scripture's controlling confession of one indivisible God.", estimatedMinutes: 10, level: "Foundational", topicSlug: "god-is-one", collection: "One God and divine identity", steps: [
    {
      title: "Begin with the confession",
      reference: "Deuteronomy 6:4",
      explanation: "Scripture does not begin by asking Israel to solve a philosophical puzzle about God's inner life. It commands them to hear and confess: the LORD our God is one LORD. That statement becomes the controlling confession for everything that follows. Whatever Scripture later reveals about God's Word, Spirit, Father, Son, or His manifestation in Christ must agree with this starting point rather than overturn it.",
      hook: "Deuteronomy gives us the confession: the LORD is one. Now Scripture itself defines how exclusive that confession is. Isaiah 43:10 asks whether any God could exist before Him or after Him."
    },
    {
      title: "No God before or after",
      reference: "Isaiah 43:10",
      explanation: "The LORD speaks in exclusive terms: no God was formed before Him, and none will exist after Him. This is stronger than a command to prefer one deity over competing deities. God denies a succession of gods around Himself. He is not one member of a divine class. His identity is unique, uncreated, and without another God before or after Him.",
      hook: "That removes any God before Him or after Him. The next question is whether another God could exist beside Him now. Isaiah 44:8 answers that directly."
    },
    {
      title: "No God beside Him",
      reference: "Isaiah 44:8",
      explanation: "God asks whether there is a God beside Him and answers His own question: He knows no other God or Rock. The force of the passage is not merely that Israel should ignore other gods. The LORD denies another divine being alongside Himself. Biblical monotheism is therefore more than exclusive worship. Scripture presents one God without a second God beside Him.",
      hook: "The prophets have defined the claim clearly. Now move into the New Testament: does Jesus preserve that same confession? Mark 12:29 gives His answer."
    },
    {
      title: "Jesus preserves the Shema",
      reference: "Mark 12:29",
      explanation: "Jesus quotes Israel's confession directly: “Hear, O Israel; The Lord our God is one Lord.” He does not replace the Shema with a new numerical confession after His coming. He places the same declaration of one LORD at the head of the greatest commandment. Any Christian understanding of Jesus must therefore preserve, not cancel, the one-God confession He Himself affirmed.",
      hook: "Jesus preserves Israel’s confession of one LORD. The final question is whether the apostles continue it after the resurrection. Paul states the answer in 1 Corinthians 8:4."
    },
    {
      title: "The apostles continue it",
      reference: "1 Corinthians 8:4",
      explanation: "Paul states that there is none other God but one. The confession of one God is not merely Old Testament background that Christianity leaves behind. It remains part of apostolic teaching inside the church. The next question is not whether Scripture has one God, but how every later revelation about Christ must be understood without creating another God beside Him.",
      hook: "The confession remains intact from Moses, through the prophets, through Jesus, and into the apostolic church. From here, the next pathway tests that claim against Scripture’s strongest statements that none is beside, with, before, or after the LORD."
    }
  ]}),
  pathway({ slug: "no-god-beside-him", title: "No God Beside Him", summary: "Follow the Bible's clearest denials of another God with, beside, before, or after the LORD.", estimatedMinutes: 9, level: "Foundational", topicSlug: "god-is-one", collection: "One God and divine identity", steps: [
    { title: "None beside Him", reference: "Deuteronomy 4:35", explanation: "The LORD reminds Israel that His acts of deliverance were meant to teach them who He is: He alone is God, and there is none else beside Him. This is not simply a warning to prefer Israel's God over idols. Moses grounds exclusive worship in what God has revealed about Himself. Before interpreting later passages about Christ, the reader must reckon with this explicit claim of divine uniqueness.", hook: "Deuteronomy 4:35 says there is none else. The next question is even more direct: does God describe any other god as existing with Him?" },
    { title: "No God with Him", reference: "Deuteronomy 32:39", explanation: "In the Song of Moses, the LORD declares that He alone is God and that no god is with Him. He connects that claim to His power over life, death, wounding, and healing. The point is not that another deity cooperates with Him, but that His authority admits no rival. This gives the study a clear standard when later Scripture speaks about God's saving work through Jesus Christ.", hook: "Deuteronomy 32:39 removes another god from God's side. Isaiah 43:10 now extends the claim across time: none before Him and none after Him." },
    { title: "None before or after", reference: "Isaiah 43:10", explanation: "Speaking to Israel as His witnesses, the LORD says no God was formed before Him and none will come after Him. God's identity cannot be explained as one god in a sequence or a class of divine beings. His claim spans past and future, leaving no room for another God to arise. Read alongside the New Testament, this becomes a question about how Jesus reveals the one eternal God, not whether Israel's God has been replaced.", hook: "Isaiah has ruled out a God before or after the LORD. Isaiah 44:6 gathers the argument into God's own titles as First and Last and denies any God beside Him." },
    { title: "First, Last, and only God", reference: "Isaiah 44:6", explanation: "The LORD identifies Himself as Israel's King and Redeemer, the First and the Last, and then says there is no God beside Him. His eternal titles and exclusive identity belong together. The passage gives the reader both a positive confession of who God is and a direct denial of any competing divine being. When these titles appear in connection with Christ, their Old Testament meaning should remain in view.", hook: "The prophetic witness is clear. The next question is whether the apostolic church keeps the same confession after Christ." },
    { title: "Apostolic continuity", reference: "1 Corinthians 8:4", explanation: "Paul addresses food offered to idols, yet he rests his instruction on the conviction that there is no other God but one. Apostolic faith does not leave Israel's monotheism behind. In the surrounding argument, Paul also speaks of one Lord, Jesus Christ, through whom are all things, so the question becomes how Christ belongs within this confession. The answer must honor both Paul's explicit oneness and his high language about Jesus.", hook: "The apostles preserve the prophetic confession of one God. From here, ask what that means for creation: did this one God create alone?" }
  ]}),
  pathway({ slug: "god-alone-creator", title: "God Alone Is Creator", summary: "Compare the LORD creating alone with New Testament creation language about Christ.", estimatedMinutes: 10, level: "Intermediate", topicSlug: "god-is-one", collection: "One God and divine identity", steps: [
    { title: "One Creator acts", reference: "Genesis 1:1", explanation: "The opening line of Genesis names God as the Creator of heaven and earth. Creation is not presented as a struggle between equal gods or the work of independent divine rivals. Everything that follows depends on the initiative of the one God who brings the world into being. This foundation matters because the New Testament will speak of creation in relation to God's Word and to Jesus Christ.", hook: "Genesis presents one acting Creator. Isaiah now lets the LORD describe that act in His own words and tells us whether anyone created alongside Him." },
    { title: "He creates alone", reference: "Isaiah 44:24", explanation: "Here the LORD says He made all things, stretched out the heavens alone, and spread abroad the earth by Himself. He leaves no unnamed divine partner standing beside Him at creation. This is stronger than saying He was the chief architect while another god assisted. Any reading of John 1 or Colossians 1 must therefore explain their creation language without contradicting the Creator's own testimony that He acted alone.", hook: "The LORD says He stretched out the heavens by Himself. The next question is how Scripture speaks about the means of that creation: His Word and breath." },
    { title: "God creates by His Word", reference: "Psalm 33:6", explanation: "The psalm celebrates the heavens being made by the word of the LORD and their host by the breath of His mouth. His word is not powerless information; what He speaks comes to pass. The poetic parallel between word and breath emphasizes God's effective creative command. This Old Testament background helps the reader approach John's language about the Word without first assuming a second, independent creator.", hook: "Psalm 33 shows God's Word as His own effective creative action. John 1 now uses that same Word-language at the opening of the Gospel." },
    { title: "All things through the Word", reference: "John 1:3", explanation: "John says that all things came into being through the Word and that nothing made came into being apart from it. The Word is placed on the Creator's side of the Creator-creation distinction, not among the things created. Read the prologue through verse 14: this same Word becomes flesh in Jesus Christ. John is pressing readers to connect the God who made everything with the One revealed in the incarnation.", hook: "John says nothing created came into being without the Word. Colossians then applies creation language directly to Christ." },
    { title: "All things in Christ", reference: "Colossians 1:16", explanation: "Paul describes creation in relation to Christ: all things in heaven and earth, visible and invisible, were created through Him and for Him. In context, Christ is not merely one more created power among the powers listed. This sweeping language must be read alongside Isaiah's claim that the LORD created alone. Apostolic interpretation sees in Christ the decisive revelation and agency of the one Creator rather than a rival source of creation.", hook: "The New Testament places Christ inside the identity and work of the one Creator. That raises the next pathway's question directly: who, then, is Jesus?" }
  ]}),
  pathway({ slug: "jesus-is-god", title: "Jesus Is God", summary: "Build a direct biblical case for the absolute deity of Jesus Christ.", estimatedMinutes: 12, level: "Foundational", topicSlug: "jesus-is-god", collection: "Jesus Christ and the incarnation", steps: [
    { title: "The promised child's identity", reference: "Isaiah 9:6", explanation: "Isaiah speaks of a child born and a son given, then attaches extraordinary royal titles to the promised ruler, including Mighty God and Everlasting Father. The child is genuinely born within human history, yet the language used of his identity exceeds an ordinary human king. This prophecy opens the question of how God's own presence and rule are revealed in the Messiah. Read it as part of Isaiah's promise of deliverance, not as an isolated title list.", hook: "Isaiah gives the promised child divine titles. Matthew now identifies the child who arrives in history as Immanuel, God with us." },
    { title: "God with us", reference: "Matthew 1:23", explanation: "Matthew interprets the birth of Jesus through the name Immanuel, which he explains as 'God with us.' The prophecy is not merely that a messenger will talk about God from a distance. In Jesus' arrival, Matthew sees God's promised presence with His people reaching its appointed fulfillment. That does not erase Jesus' genuine human birth; it gives the birth its theological weight. The one who saves is the one in whom God has come near.", hook: "Matthew tells us God is with us in Jesus. John goes behind the birth and identifies the Word who becomes flesh as God." },
    { title: "The Word was God", reference: "John 1:1", explanation: "John carefully holds two statements together: the Word was with God, and the Word was God. The Word is not treated as a created thing, and its full divine identity is not diminished. The prologue reaches its turning point in verse 14, when the Word becomes flesh. The argument is therefore about God's eternal self-expression entering human history in Jesus Christ, not merely about a religious teacher who resembles God.", hook: "John establishes the deity of the Word. Paul next describes the saving event itself as God acting in Christ." },
    { title: "God in Christ", reference: "2 Corinthians 5:19", explanation: "Paul says that God was in Christ reconciling the world to Himself, and he identifies God as the source of the saving initiative. The language centers the work of reconciliation in God acting through Christ; it is not a claim that humanity saved itself. Read the wider paragraph: Christ dies, sin is dealt with, and believers become ambassadors of that reconciliation. The passage joins the reality of Jesus' human mission to God's own saving presence.", hook: "If God Himself is reconciling the world in Christ, Colossians tells us how fully the divine presence dwells in Him." },
    { title: "All divine fullness", reference: "Colossians 2:9", explanation: "Paul does not say that a portion of deity visited Jesus temporarily. He says that all the fullness of the Godhead dwells in Christ bodily. The statement occurs in a warning against teachings that would diminish Christ's sufficiency or direct believers elsewhere for spiritual completion. His bodily existence does not cancel divine fullness; it is where Paul says that fullness dwells. This verse is central to the apostolic confession of God fully revealed in Jesus.", hook: "Paul says all the fullness of deity dwells bodily in Christ. Thomas then gives the personal confession that matches that claim." },
    { title: "My Lord and my God", reference: "John 20:28", explanation: "When Thomas encounters the risen Jesus, he answers Him, 'My Lord and my God.' The confession is addressed to Jesus, not merely spoken about God in the abstract. John records it near the climax of his Gospel and then states his purpose: that readers believe Jesus is the Christ, the Son of God, and have life through His name. The Gospel brings resurrection faith and the acknowledgment of Jesus' divine identity together.", hook: "Thomas calls the risen Jesus his Lord and his God. The next pathway asks how Scripture explains this: the Word who was God became flesh." }
  ]}),
  pathway({ slug: "word-became-flesh", title: "The Word Became Flesh", summary: "Follow God's eternal Word into the genuine humanity of Jesus Christ.", estimatedMinutes: 11, level: "Intermediate", topicSlug: "the-word-became-flesh", collection: "Jesus Christ and the incarnation", steps: [
    { title: "The Word was God", reference: "John 1:1", explanation: "John opens before the created world, identifying the Word as both with God and God. That double affirmation must be allowed to stand rather than reducing the Word to a mere sound or treating it as a creature. John's emphasis is that God's Word belongs to His eternal divine reality. The later claim that this Word became flesh makes the prologue essential for understanding who Jesus is and what the incarnation means.", hook: "John begins by identifying the Word as God. The next verse in the argument asks what relationship this Word has to creation." },
    { title: "Creation through the Word", reference: "John 1:3", explanation: "The Word is the means through which all created things came to be; John deliberately excludes even one created exception. This makes the Word foundational to creation rather than part of the created order. The statement also recalls Genesis, where God brings things into existence by speaking. Continue to verse 14, because John's purpose is not simply to explain creation but to identify the Word now present in Jesus Christ.", hook: "Everything created comes through the Word. Psalm 33 supplies the Old Testament pattern for understanding God's Word as His own creative self-expression." },
    { title: "The Old Testament background", reference: "Psalm 33:6", explanation: "Psalm 33 joins God's word and the breath of His mouth in its praise of the Creator. The focus is on the LORD's power to bring things into existence by His own command, not on a partnership between competing gods. This is important background for reading the language of the Word in John's prologue. Scripture first presents God's word as inseparable from His effective will and creative action.", hook: "The Old Testament shows God creating by His own Word and breath. John 1:14 is the turning point: that Word becomes flesh." },
    { title: "The turning point", reference: "John 1:14", explanation: "The decisive turn in John's prologue is not that the Word spoke to a human being, but that the Word became flesh and dwelt among us. John says the disciples beheld His glory, full of grace and truth. Flesh means genuine human life, not a costume or a temporary appearance. The One John has described in creation and divine identity is now encountered in the historical person of Jesus Christ.", hook: "The Word does not merely visit flesh. The Word becomes flesh. Luke 1:35 then explains how the holy child is called the Son of God." },
    { title: "The holy child called Son", reference: "Luke 1:35", explanation: "Gabriel explains that the Holy Ghost will come upon Mary and the power of the Highest will overshadow her; therefore the holy child will be called the Son of God. The text connects the promised child's identity to God's miraculous action in conception. It shows the reality of Jesus' human beginning without saying that the divine Word began to exist then. Hold the miracle of His birth alongside John's declaration of the eternal Word.", hook: "Luke ties the title Son of God to the miraculous conception and birth. The next pathway follows Sonship through that real human life." }
  ]}),
  pathway({ slug: "son-was-born", title: "The Son Was Born", summary: "Trace Sonship through conception, birth, human life, and saving mission.", estimatedMinutes: 10, level: "Intermediate", topicSlug: "the-son-of-god", collection: "Jesus Christ and the incarnation", steps: [
    { title: "A child born, a Son given", reference: "Isaiah 9:6", explanation: "Isaiah places the birth of a child and the giving of a son within a promise of peace, justice, and Davidic rule. The same verse assigns the coming ruler titles associated with divine power and enduring fatherly care. The text therefore holds real birth and extraordinary identity together. It does not permit us to ignore Jesus' humanity, but neither does it allow us to describe the promised Son as only an ordinary human king.", hook: "Isaiah joins a born child with divine identity. Luke now tells us how that promised Son enters history." },
    { title: "Therefore called Son", reference: "Luke 1:35", explanation: "Gabriel says the Holy Ghost will come upon Mary and that the holy thing born of her will be called the Son of God. The word 'therefore' links this announcement of sonship to God's act in the conception. Luke is emphasizing that this child belongs uniquely to God and comes by divine initiative. The verse explains the birth announcement; wider claims about the nature of God must still be tested against the whole scriptural witness.", hook: "The angel connects the title Son of God to the holy child conceived by the Holy Ghost. Paul next anchors that Sonship in real human birth." },
    { title: "Made of a woman", reference: "Galatians 4:4", explanation: "Paul says God sent forth His Son when the fullness of time came, born of a woman and born under the law. The saving mission enters actual human history and the covenant obligations of Israel. The next verse gives the purpose: to redeem those under the law so believers might receive adoption. The Son does not rescue humanity by avoiding human life; He enters it to accomplish redemption.", hook: "The Son is made of a woman and enters human history under the law. Luke then shows that this humanity is not an appearance: Jesus truly grows." },
    { title: "The Son truly grows", reference: "Luke 2:52", explanation: "Luke says Jesus increased in wisdom, stature, and favor with God and people. Those are genuine features of a human life, not empty appearances. His growth should not be explained away merely because the New Testament also speaks of divine fullness dwelling in Him. The incarnation requires taking both sets of testimony seriously: Jesus shares real human development, and God's saving presence is revealed in Him.", hook: "Jesus increases in wisdom and stature. The next question is what that real humanity means for His role between God and humanity." },
    { title: "The man Christ Jesus", reference: "1 Timothy 2:5", explanation: "Paul begins with one God and one mediator between God and humanity, the man Christ Jesus, who gave Himself as a ransom. The mediator's humanity matters because He truly represents those He came to save. The verse does not introduce a second God to negotiate with the first. It explains how the saving work of the one God reaches people through the genuine human obedience and self-giving of Jesus Christ.", hook: "Paul calls Him the man Christ Jesus, the true human mediator before the one God. The next pathway asks how the Father is present and working in that Son." }
  ]}),
  pathway({ slug: "father-dwells-in-son", title: "The Father Dwells in the Son", summary: "Use Jesus' own explanation of the Father's presence and work in Him.", estimatedMinutes: 9, level: "Foundational", topicSlug: "the-father-in-the-son", collection: "Jesus Christ and the incarnation", steps: [
    { title: "Knowing Jesus, knowing the Father", reference: "John 14:7", explanation: "Jesus tells His disciples that knowing Him means knowing His Father also. Philip's request in the next verse reveals that the disciples have not yet grasped the force of that claim. Jesus is not simply directing them to an absent God whom He knows better than they do. His person and works are the decisive revelation of the Father. The surrounding conversation explains how the Father is made known in and through the Son.", hook: "Jesus says knowing Him brings knowledge of the Father. Philip's request to see the Father lets Jesus make the claim even more explicit." },
    { title: "Seeing Jesus, seeing the Father", reference: "John 14:9", explanation: "Philip asks Jesus to show them the Father, and Jesus answers by asking how Philip can say that after seeing Him. Jesus does not dismiss the Father's reality; He challenges Philip to recognize the Father revealed in the Son standing before him. The point is more demanding than saying Jesus resembles God's character. In the context of John 14, Jesus makes the unseen Father known through His own words and works.", hook: "Jesus answers the desire to see the Father by pointing to Himself. He then explains why: the Father dwells in Him and performs the works." },
    { title: "The Father dwells and works", reference: "John 14:10", explanation: "Jesus explains His answer to Philip: He is in the Father, the Father is in Him, and the Father dwelling in Him performs the works. The statement is about divine presence and action, not merely a close partnership between two teachers. Jesus distinguishes His speech from the Father's works while presenting the Father as genuinely present in Him. The apostolic reading must preserve the full force of that indwelling without denying Jesus' real humanity.", hook: "The works are the Father's works from within Christ. Paul carries that same pattern into salvation and says God was in Christ reconciling the world." },
    { title: "God reconciling in Christ", reference: "2 Corinthians 5:19", explanation: "Paul says God was in Christ reconciling the world to Himself and not counting people's trespasses against them. God is not a distant observer waiting while someone else independently accomplishes redemption. Christ's mission is the place where God's own reconciling action meets humanity. Read the surrounding verses, which distinguish God's initiative, Christ's work, and the apostles' message, so the statement is not reduced to a slogan detached from the gospel.", hook: "Reconciliation is God's own action in Christ. Colossians now states the extent of that indwelling without qualification." },
    { title: "All fullness bodily", reference: "Colossians 2:9", explanation: "Colossians states that all the fullness of the Godhead dwells in Christ bodily. This deepens the language of the Father dwelling and working in the Son: Paul does not describe a limited measure of divine help. He places complete divine fullness in the embodied Christ. In context, believers are warned against seeking completion through teachings or powers outside Him. The sufficiency of Jesus rests on who is present in Him.", hook: "All the fullness of deity dwells bodily in Christ. The next pathway asks how the invisible God can therefore be seen and known in Jesus." }
  ]}),
  pathway({ slug: "jesus-image-of-god", title: "Jesus Is the Image of God", summary: "See how the invisible God becomes visible and knowable in Christ.", estimatedMinutes: 9, level: "Intermediate", topicSlug: "the-father-in-the-son", collection: "Jesus Christ and the incarnation", steps: [
    { title: "The unseen God declared", reference: "John 1:18", explanation: "John says no one has seen God at any time and that the Son has made Him known. The passage holds together God's invisibility and His genuine self-disclosure through Jesus. The Son does not make God known merely by providing information; John's Gospel presents His life as the revelation of the Father's character, will, and saving purpose. This is the starting point for understanding why Scripture can call Christ the image of the invisible God.", hook: "John begins with the invisible God being made known. Jesus' answer to Philip shows what that revelation looks like in a human life." },
    { title: "The Father seen in Jesus", reference: "John 14:9", explanation: "When Philip asks to see the Father, Jesus points to His own presence among the disciples. The answer makes sense because the Father has been disclosed in what Jesus says and does. It does not teach that the invisible Father has become visible independently of the incarnate Son. Rather, the disciples are to recognize God's revelation in Jesus Christ. The surrounding verses ground this in the Father dwelling and working in Him.", hook: "Jesus says seeing Him is seeing the Father. Paul gives that same truth a compact title: Christ is the image of the invisible God." },
    { title: "Image of the invisible God", reference: "Colossians 1:15", explanation: "Paul calls Christ the image of the invisible God while describing His supremacy over creation. An image makes known what cannot otherwise be seen; in Jesus, the invisible God is revealed to humanity. Paul's next lines connect Christ to the existence and purpose of all things, so this is not merely a statement that Jesus was a good moral example. The reader must account for the extraordinary divine significance Paul gives the person of Christ.", hook: "Christ is the visible image of the invisible God. The next question is whether that image is partial or complete." },
    { title: "Fullness dwelling", reference: "Colossians 1:19", explanation: "Paul says that all fullness was pleased to dwell in Christ. Read with the surrounding verses, this fullness belongs to the One through whom God reconciles all things by the blood of His cross. Christ reveals the invisible God not only through words but through God's saving presence and action in His life and death. Colossians 2:9 will sharpen this statement by naming the fullness as the fullness of the Godhead dwelling bodily.", hook: "Paul says all fullness dwells in Christ. Hebrews then describes the Son as the radiance and exact expression of God's being." },
    { title: "Exact expression", reference: "Hebrews 1:3", explanation: "Hebrews describes the Son as the radiance of God's glory and the express image of His person, while saying He upholds all things by His powerful word. This is far stronger than describing a faithful prophet who merely imitates God. At the same time, the chapter speaks of the Son's saving work and exaltation. The reader must take seriously both the extraordinary revelation of God's identity in Christ and the real messianic mission He fulfills.", hook: "Hebrews presents the Son as the exact expression of divine glory. The next pathway focuses on the reason this revelation is complete: all the Godhead dwells bodily in Christ." }
  ]}),
  pathway({ slug: "fullness-of-godhead", title: "The Fullness of the Godhead", summary: "Build Paul's case that God's complete fullness dwells bodily in Jesus Christ.", estimatedMinutes: 9, level: "Intermediate", topicSlug: "jesus-is-god", collection: "Jesus Christ and the incarnation", steps: [
    { title: "God in Christ", reference: "2 Corinthians 5:19", explanation: "The starting point is not an abstract theory of divine composition. Paul says God was in Christ reconciling the world to Himself. The saving initiative belongs to God, and the work takes place in the historical life and mission of Jesus. This prepares the reader for Paul's fuller statement in Colossians: the presence of God in Christ is not partial or incidental. The message of reconciliation rests on God truly acting in His Messiah.", hook: "Paul begins with God acting in Christ. Jesus Himself explains that action as the Father dwelling and working in Him." },
    { title: "The Father dwelling", reference: "John 14:10", explanation: "Jesus tells His disciples that the Father dwelling in Him does the works. His miracles and teaching are presented as the activity of God revealed through the Son, not as the acts of a second rival deity. The context also shows Jesus speaking and obeying as the incarnate Son. The importance of this verse is the connection between divine indwelling and Christ's visible ministry. It gives concrete form to what divine fullness means.", hook: "Jesus identifies the indwelling Father as the source of the works. Colossians next describes Christ as the visible image of the invisible God." },
    { title: "The visible image", reference: "Colossians 1:15", explanation: "Paul names Christ the image of the invisible God. The invisible God has not ceased to be God or become one creature among many; rather, Jesus makes Him known. In the same passage, Paul describes Christ's relation to creation and His preeminence over all things. This prepares for the fullness language that follows. The image of God is not an empty sign pointing away from Christ, because God's saving revelation is present in Him.", hook: "Christ makes the invisible God visible. Paul then explains why the image lacks nothing: all fullness dwells in Him." },
    { title: "All fullness", reference: "Colossians 1:19", explanation: "Within a hymn about Christ's supremacy and reconciliation, Paul says that all fullness was pleased to dwell in Him. The word 'all' resists any account in which Christ possesses only a small portion of what God is. Verse 20 connects this indwelling to peace made through the blood of His cross. Divine fullness and genuine human suffering therefore meet in the same Messiah. Paul will make the bodily dimension explicit in the next chapter.", hook: "All fullness dwells in Christ. Colossians 2:9 removes any remaining ambiguity by saying that fullness is the fullness of deity dwelling bodily." },
    { title: "All fullness bodily", reference: "Colossians 2:9", explanation: "Colossians 2:9 states that in Christ dwells all the fullness of the Godhead bodily. Paul's warning is that believers must not be drawn away from Christ by teachings promising a higher spiritual fullness elsewhere. All fullness, not a fragment, dwells in the embodied Jesus. The verse does not erase the distinction between deity and humanity; it declares that the incarnate Christ is the dwelling of full deity. That makes Jesus sufficient for salvation and spiritual life.", hook: "The whole argument arrives here: all the fullness of the Godhead dwells bodily in Christ. From that identity, the next pathway follows the saving name revealed in Jesus." }
  ]}),
  pathway({ slug: "name-of-jesus", title: "The Name of Jesus", summary: "Follow the saving name through revelation, salvation, worship, and baptism.", estimatedMinutes: 11, level: "Foundational", topicSlug: "the-name-of-jesus", collection: "Salvation and new birth", steps: [
    { title: "The saving name given", reference: "Matthew 1:21", explanation: "Matthew says the child is to be named Jesus because He will save His people from their sins. His name is inseparable from His mission. It is not presented as a lucky sound or a formula with power apart from the person who bears it. The angel announces what God will accomplish through this child. Matthew immediately connects the birth to Immanuel, 'God with us,' inviting the reader to see divine saving presence in Jesus.", hook: "Matthew connects the name Jesus to His saving mission. John then shows that Jesus' ministry also reveals and manifests the Father's name." },
    { title: "The Father's name manifested", reference: "John 17:6", explanation: "In His prayer, Jesus says He has manifested the Father's name to the people given Him. In Scripture, a name can disclose a person's character, authority, and identity, not just a sequence of syllables. Jesus has made the Father known through His life and teaching. The verse does not explicitly claim that every biblical title for God is literally the same word. It establishes that the Father's revelation reaches the disciples through the Son.", hook: "Jesus says He manifested the Father's name. Acts now shows where the apostles locate salvation after the resurrection." },
    { title: "No other saving name", reference: "Acts 4:12", explanation: "Peter declares that salvation is found in no other and that no other name under heaven has been given among people by which we must be saved. He is speaking about the risen Jesus whom the authorities rejected and God raised. The exclusivity belongs to Christ Himself, not to a technique for pronouncing His name. This is why apostolic preaching, healing, and baptism repeatedly center on the authority of Jesus Christ.", hook: "The apostles declare no other saving name. Philippians expands the claim from salvation into universal confession and worship." },
    { title: "The name above every name", reference: "Philippians 2:9–11", explanation: "Paul says God highly exalted Jesus and gave Him the name above every name, so every knee will bow and every tongue confess Jesus Christ as Lord. The wording echoes Isaiah's language about universal acknowledgment of the LORD. Paul applies that worship-filled confession to Jesus while saying it is to the glory of God the Father. The verse joins the Messiah's exaltation to the highest divine honor without treating His name as mere branding.", hook: "The name of Jesus stands above every name and every knee bows. Colossians then brings that authority into the believer's ordinary words and actions." },
    { title: "Everything in Jesus' name", reference: "Colossians 3:17", explanation: "Paul instructs believers to do everything, in word or deed, in the name of the Lord Jesus while giving thanks to God the Father through Him. His name marks the authority under which the whole Christian life is lived. This reaches beyond public religious rites into speech, relationships, and ordinary conduct. A profession of Jesus' name should therefore result in a life shaped by His teaching, character, and lordship.", hook: "Everything is brought under the name of the Lord Jesus. The next pathway asks how Jesus' command to baptize into the singular name was carried out by His apostles." }
  ]}),
  pathway({ slug: "matthew-28-and-acts-2", title: "Matthew 28:19 and Acts 2:38", summary: "Read Jesus' command and its apostolic fulfillment together.", estimatedMinutes: 10, level: "Foundational", topicSlug: "the-name-of-jesus", collection: "Salvation and new birth", steps: [
    { title: "Notice the singular name", reference: "Matthew 28:19", explanation: "Jesus commands the disciples to baptize in the singular 'name' of the Father, Son, and Holy Ghost. The singular wording is significant, but grammar alone does not identify the spoken baptismal wording. The next task is to compare the commission with the apostles' recorded practice rather than assuming the accounts contradict one another. Apostolic interpreters understand Jesus' name as the revealed authority in which the command is obeyed; other Christians read the formula differently.", hook: "Jesus commands baptism into a singular name. Luke's account of the same commission helps identify how that name functions in the gospel mission." },
    { title: "The commission in His name", reference: "Luke 24:46–47", explanation: "Luke records the risen Jesus declaring that repentance and remission of sins should be preached in His name among all nations, beginning at Jerusalem. This parallels Matthew's universal commission and identifies the authority behind the message. Luke emphasizes proclamation rather than quoting the exact words said over a baptismal candidate. The connection matters because Acts immediately shows the Jerusalem mission beginning under the authority of Jesus Christ.", hook: "Luke says repentance and remission are to be preached in His name. Acts 2 shows the apostles carrying out that commission for the first time." },
    { title: "The apostles begin the mission", reference: "Acts 2:38", explanation: "When the crowd asks what it should do, Peter commands repentance and baptism in the name of Jesus Christ for the remission of sins and promises the gift of the Holy Ghost. Acts presents this as the first public apostolic response after Pentecost, not as a private preference of Peter. Apostolic readers take it as the practical enactment of the risen Lord's commission. To assess that claim fairly, follow the baptismal accounts beyond Jerusalem as well.", hook: "Peter commands baptism in the name of Jesus Christ. The next question is whether that wording was only for Pentecost or became the continuing apostolic pattern." },
    { title: "The pattern crosses boundaries", reference: "Acts 8:16", explanation: "Acts says the Samaritans had been baptized in the name of the Lord Jesus, yet the Holy Ghost had not fallen on them before Peter and John came. The narrative separately identifies water baptism and the reception of the Spirit. It also shows that Jesus' name was not limited to the Jerusalem audience. This repeated description strengthens the question of how the apostles understood the commission, though Acts does not reproduce every baptismal ceremony word for word.", hook: "The Samaritan mission repeats baptism in the name of the Lord Jesus. Acts 19 shows the same pattern when Paul encounters disciples with an incomplete baptism." },
    { title: "The pattern is corrected and repeated", reference: "Acts 19:5", explanation: "At Ephesus, Paul learns that certain disciples know only John's baptism. After they hear about Jesus, they are baptized in the name of the Lord Jesus and then receive the Holy Ghost when Paul lays hands on them. The account shows that the name of Jesus remains central as the gospel spreads. Read alongside Acts 2 and 8, it establishes a consistent apostolic description of baptism. The interpretive debate is how that practice relates to Matthew's wording.", hook: "Paul baptizes them in the name of the Lord Jesus. The next pathway follows that baptismal language across Acts and then asks what baptism means in the epistles." }
  ]}),
  pathway({ slug: "baptism-in-jesus-name", title: "Baptism in Jesus' Name", summary: "Follow the explicit baptismal language and its meaning through Acts and the epistles.", estimatedMinutes: 12, level: "Foundational", topicSlug: "the-name-of-jesus", collection: "Salvation and new birth", steps: [
    { title: "The risen Lord's commission", reference: "Luke 24:46–47", explanation: "The risen Jesus says that His suffering and resurrection fulfill Scripture and that repentance and remission of sins are to be preached in His name to all nations. The name is tied to the authority of the crucified and risen Messiah, not to a detached ritual phrase. Acts begins in Jerusalem, just as Jesus instructed. Comparing Luke's commission with Peter's preaching helps explain why Jesus' name becomes central in the apostolic response.", hook: "The risen Jesus commissions repentance and remission in His name. Acts 2 shows the first direct apostolic response to that command." },
    { title: "The first apostolic response", reference: "Acts 2:38", explanation: "At Pentecost, convicted hearers ask what they should do. Peter responds with repentance, baptism in the name of Jesus Christ for remission of sins, and the promise of the gift of the Holy Ghost. The command is addressed to people who have heard the gospel of Jesus' death, resurrection, and exaltation. Baptism is therefore connected to a repentant response to Christ, not treated as a substitute for faith or a mechanical act.", hook: "Peter joins repentance, Jesus-name baptism, and the gift of the Holy Ghost. Acts 8 tests whether the baptismal pattern continues beyond Jerusalem." },
    { title: "The pattern continues", reference: "Acts 8:16", explanation: "Philip's mission in Samaria produces believers who are baptized in the name of the Lord Jesus. Acts then records that Peter and John come and pray for the believers to receive the Holy Ghost. The story distinguishes water baptism from the reception of the Spirit while placing both within the church's mission. It also shows that baptism in Jesus' name is not unique to one Jerusalem sermon; the same language appears among new believers elsewhere.", hook: "Samaritan believers are baptized in the name of the Lord Jesus. Acts 10 asks whether Spirit-filled Gentiles are exempt from water baptism." },
    { title: "Gentiles are commanded", reference: "Acts 10:47–48", explanation: "While Peter is preaching, the Holy Ghost falls on Gentile hearers before they are baptized. Peter does not conclude that receiving the Spirit makes water baptism unnecessary. Instead, he asks who could forbid water and commands them to be baptized in the Lord's name. The order differs from Acts 2, but both Spirit reception and baptism remain part of the account. God's initiative is clear, and the Gentiles are brought into the same apostolic fellowship.", hook: "Peter still commands water baptism after the Gentiles receive the Spirit. Romans now explains the meaning of baptism by connecting it to Christ's death and burial." },
    { title: "Buried with Christ", reference: "Romans 6:3–4", explanation: "Paul explains that those baptized into Jesus Christ are baptized into His death and buried with Him, so they may walk in newness of life as Christ was raised. This is more than an outward badge with no relation to the gospel. Baptism visibly identifies believers with Christ's death and burial and points toward transformed living. Paul's emphasis is not on the water as an independent power, but on union with the crucified and risen Lord.", hook: "Baptism joins the believer to Christ's death and burial. Colossians makes clear that this is not confidence in a ritual but faith in God's operation." },
    { title: "Faith in God's operation", reference: "Colossians 2:12", explanation: "Paul speaks of being buried with Christ in baptism and raised with Him through faith in the working of God who raised Jesus from the dead. The saving power belongs to God, and faith is explicitly present in the description. This guards against treating baptism as human merit or a ceremony that functions apart from trusting Christ. In the surrounding verses, forgiveness and new life are grounded in what God accomplishes through Jesus.", hook: "Baptism is an obedient act of faith in God's saving work. The next pathway places baptism inside Jesus' larger teaching about being born of water and Spirit." }
  ]}),
  pathway({ slug: "new-birth", title: "The New Birth", summary: "Connect Jesus' teaching about water and Spirit with the apostolic response in Acts.", estimatedMinutes: 12, level: "Foundational", topicSlug: "the-new-birth", collection: "Salvation and new birth", steps: [
    { title: "Birth from above required", reference: "John 3:3", explanation: "Nicodemus comes to Jesus as a religious teacher, but Jesus tells him that no one can see the kingdom of God without being born again, or from above. Religious knowledge, ancestry, and familiarity with miracles are not the same as receiving new life from God. The statement creates the question Nicodemus asks next: how can someone be born anew? Jesus' answer turns the conversation toward water, Spirit, and God's transforming action.", hook: "Jesus makes the new birth necessary for seeing the kingdom. He immediately defines that birth more specifically in terms of water and Spirit." },
    { title: "Water and Spirit", reference: "John 3:5", explanation: "Jesus says that no one can enter God's kingdom without being born of water and of the Spirit. The surrounding conversation contrasts natural birth with the work of the Spirit and emphasizes God's initiative. Apostolic teaching connects this language with the baptismal and Spirit-reception pattern seen in Acts. Christians differ on the precise meaning of 'water,' so the best study compares this verse with the larger New Testament witness rather than isolating the phrase.", hook: "Jesus says entrance into the kingdom requires birth of water and Spirit. Acts 2 shows how the apostles answer people who ask what they must do." },
    { title: "The apostolic answer", reference: "Acts 2:37–38", explanation: "When the Pentecost crowd is pierced by Peter's preaching, he calls them to repent, be baptized in the name of Jesus Christ, and receive the gift of the Holy Ghost. The response is not presented as a philosophical definition of new birth but as the concrete answer to people seeking salvation. Apostolic readers see the water-and-Spirit language of John 3 reflected here. The reader should hold together faith in Christ, repentance, baptism, and God's promised Spirit.", hook: "Peter answers conviction with repentance, baptism, and the gift of the Holy Ghost. The next verse tells us whether that promise was limited to the first audience." },
    { title: "The promise continues", reference: "Acts 2:39", explanation: "Peter says the promise is for the hearers, their children, and all who are far off, as many as the Lord our God shall call. The gift is not restricted to the first group gathered in Jerusalem. The wording anticipates the gospel's movement beyond the original audience. It also keeps the emphasis on God's call rather than a human ability to manufacture spiritual life. The invitation extends as far as God calls people to Himself.", hook: "The promise reaches children, those far off, and all whom God calls. Acts 8 then shows that water baptism and receiving the Spirit can be distinguished in experience." },
    { title: "Water and Spirit distinguished", reference: "Acts 8:14–17", explanation: "In Samaria, people had received the word of God and been baptized in Jesus' name, yet the narrative says the Holy Ghost had not yet fallen on them. Peter and John come, pray, and lay hands on them. This passage keeps the acts of baptism and Spirit reception distinguishable within the same conversion story. It challenges any assumption that Luke always describes these experiences as happening simultaneously or in only one fixed order.", hook: "The Samaritans had been baptized but still needed to receive the Spirit. Titus brings washing and Spirit-renewal together under the saving mercy of God." },
    { title: "Washing and renewal", reference: "Titus 3:5–6", explanation: "Paul says salvation comes not by works of righteousness we have performed, but according to God's mercy, by the washing of regeneration and renewing of the Holy Ghost. He immediately speaks of the Spirit being poured out through Jesus Christ our Savior. The emphasis is God's merciful action producing new life. Apostolic readers connect this with water and Spirit, while the passage itself insists that transformation cannot be claimed as something people earn.", hook: "Paul joins washing and renewal by the Holy Ghost without making either a work of human merit. The next pathway isolates the first movement of that response: repentance." }
  ]}),
  pathway({ slug: "repentance", title: "Repentance", summary: "See repentance as a commanded turning toward God, not mere regret.", estimatedMinutes: 9, level: "Foundational", topicSlug: "the-new-birth", collection: "Salvation and new birth", steps: [
    { title: "Jesus opens with repentance", reference: "Mark 1:15", explanation: "Jesus begins His public proclamation by announcing that the time is fulfilled, God's kingdom has drawn near, and people must repent and believe the gospel. Repentance and faith belong together in this call. Turning from sin is not merely feeling bad about past choices; it means responding to God's reign with a changed direction. The gospel announces good news, but it also demands an answer from those who hear it.", hook: "Jesus opens His kingdom preaching with repentance and faith. Luke 13 shows that repentance is not optional language but a necessary turning." },
    { title: "Repentance is necessary", reference: "Luke 13:3", explanation: "Jesus' warning comes after people discuss tragic deaths and wonder whether the victims were worse sinners. He refuses that comparison and tells His hearers that they themselves must repent. Repentance is not a tool for judging other people's misfortunes; it is an urgent call to examine one's own life before God. The verse directs attention away from ranking sins and toward the universal need to turn to Him.", hook: "Jesus warns that people must repent. After His resurrection, He places that same call inside the worldwide gospel commission." },
    { title: "Part of the commission", reference: "Luke 24:46–47", explanation: "After His resurrection, Jesus explains that the Christ was to suffer and rise and that repentance and remission of sins should be proclaimed in His name among all nations. Repentance is therefore part of the gospel mission authorized by Jesus Himself. It is neither an optional moral improvement project nor a message separate from His saving death and resurrection. The same commission provides the setting for Peter's call to repent at Pentecost.", hook: "The risen Christ commands repentance and remission to be preached to all nations. Acts 2 shows what that command sounds like when hearers are convicted." },
    { title: "The first response", reference: "Acts 2:37–38", explanation: "The hearers ask what they should do after Peter proclaims Jesus as the crucified and risen Lord. Peter's first command is to repent, followed by baptism in Jesus' name and the promise of the Holy Ghost. Repentance responds to the truth about Christ and changes the hearer's direction. It is not an attempt to purchase forgiveness by performing enough good deeds; it is the surrendered response of a person convicted by the gospel.", hook: "Peter's first answer is direct: repent. Paul then helps distinguish true repentance from emotion that never produces a changed direction." },
    { title: "Godly sorrow produces change", reference: "2 Corinthians 7:10", explanation: "Paul distinguishes godly sorrow from the sorrow of the world. Godly sorrow produces repentance leading to salvation, while worldly sorrow ends in death. The difference is not simply how intensely someone feels guilt, but whether the sorrow leads to a genuine turn toward God. In the surrounding letter, Paul describes the Corinthians' earnestness and changed conduct. The evidence of repentance includes a response that moves beyond regret into action.", hook: "Godly sorrow produces repentance that leads toward salvation. The next pathway follows the promised gift that accompanies the apostolic response: receiving the Holy Ghost." }
  ]}),
  pathway({ slug: "receiving-the-holy-ghost", title: "Receiving the Holy Ghost", summary: "Trace the promise, reception, and recognizable experience of the Holy Ghost.", estimatedMinutes: 12, level: "Foundational", topicSlug: "the-new-birth", collection: "Salvation and new birth", steps: [
    { title: "The promise", reference: "Joel 2:28–29", explanation: "Through Joel, God promises to pour out His Spirit on all flesh, including sons, daughters, servants, and handmaids. The promise breaks through ordinary divisions of age, status, and gender in prophetic service. Peter later cites this passage to explain what the crowd is seeing at Pentecost. The point is that the outpouring comes from God and belongs to His promised work in the last days, not to a private spiritual achievement.", hook: "Joel promises a future outpouring of God's Spirit across generations. Jesus then describes that promised Spirit as moving from being with the disciples to dwelling in them." },
    { title: "With you and in you", reference: "John 14:16–18", explanation: "Jesus promises another Comforter, the Spirit of truth, who will abide with His disciples, and then says He will not leave them comfortless but will come to them. The passage emphasizes God's continuing presence with believers after Jesus' departure. The disciples are not being promised mere inspiration from a distant teacher. Read the words 'with you' and 'in you' alongside Jesus' larger farewell discourse to understand the Spirit's abiding work.", hook: "Jesus promises the Comforter will dwell in His people. Acts 2 records the moment that promise becomes an experienced reality." },
    { title: "The promise arrives", reference: "Acts 2:1–4", explanation: "On Pentecost, the disciples are gathered together when the Holy Ghost fills them, and they begin to speak with other tongues as the Spirit gives utterance. The narrative highlights divine initiative, audible speech, and the public response of the crowd. Peter explains the event as the fulfillment of God's promise, not as an isolated experience meant only to entertain observers. The new covenant community is empowered for witness through God's Spirit.", hook: "At Pentecost they are filled and speak as the Spirit gives utterance. Peter then tells the crowd whether this gift belongs only to the people in the upper room." },
    { title: "Promised to those God calls", reference: "Acts 2:38–39", explanation: "Peter joins the promise of the Holy Ghost to the call to repent and be baptized in Jesus' name. He then expands the promise to the next generation and to those far away whom God will call. The gift is not limited to the apostles in the upper room. Because the Spirit is a gift from God, it must not be reduced to a status people can earn or a technique they can control.", hook: "Peter extends the promise to all whom God calls. Acts 10 shows that promise crossing into the Gentile world in a way the Jewish believers can recognize." },
    { title: "Gentiles visibly receive", reference: "Acts 10:44–46", explanation: "While Peter speaks in Cornelius's house, the Holy Ghost falls on Gentile listeners. The Jewish believers recognize that the gift has been poured out on them because they hear them speak with tongues and magnify God. This matters because Gentile inclusion is confirmed by God's own action before water baptism. The sign is not described as a mere inward feeling; Luke records what the witnesses heard and how they interpreted it.", hook: "The Gentiles' reception is recognized by what the believers hear. Acts 19 shows Paul still asking disciples whether they have received the Holy Ghost." },
    { title: "Believers asked and filled", reference: "Acts 19:1–6", explanation: "Paul meets disciples at Ephesus and asks whether they have received the Holy Ghost since they believed. After explaining Jesus and baptizing them in His name, he lays hands on them; the Holy Ghost comes upon them, and they speak with tongues and prophesy. Luke records a deliberate concern for reception, not just for religious identification. The account links Christ-centered teaching, baptism, and observable Spirit activity while showing the Spirit remains God's gift.", hook: "The Ephesian disciples receive the Spirit in an observable way. The next pathway examines the repeated sign that accompanies Spirit reception in Acts." }
  ]}),
  pathway({ slug: "tongues-as-initial-sign", title: "Tongues as the Initial Sign", summary: "Distinguish the repeated reception sign in Acts from the public gift in Corinthians.", estimatedMinutes: 11, level: "Intermediate", topicSlug: "the-new-birth", collection: "Salvation and new birth", steps: [
    { title: "All speak at Pentecost", reference: "Acts 2:1–4", explanation: "Acts says the believers were all filled with the Holy Ghost and began speaking with other tongues as the Spirit gave utterance. At Pentecost, tongues accompany the first recorded outpouring of the promised Spirit. This is the foundation of the apostolic teaching about an initial outward sign. The passage itself describes this group and this event; the broader claim about every believer must be tested against the other reception accounts and Paul's teaching.", hook: "At Pentecost everyone filled speaks with other tongues. Peter then describes the outpouring as something that could be seen and heard." },
    { title: "Seen and heard", reference: "Acts 2:33", explanation: "Peter explains that the exalted Jesus has poured out what the crowd can 'see and hear.' Pentecost is not treated as a purely invisible occurrence. The public manifestations lead Peter to preach Jesus' resurrection and exaltation. This supports the idea that Spirit reception can be outwardly recognizable. By itself, however, the verse does not specify every manifestation or settle whether one sign must occur in every Christian conversion.", hook: "Peter treats the Spirit's arrival as observable. Acts 10 gives the clearest example of how believers recognized that Gentiles had received the same gift." },
    { title: "The identifying sign", reference: "Acts 10:44–46", explanation: "In Cornelius's house, Jewish believers know that the Gentiles have received the Holy Ghost because they hear them speak with tongues and magnify God. Luke explicitly supplies the reason they recognized the gift. The account is important evidence for the apostolic claim that tongues may accompany initial Spirit reception. It also shows that God acted before the visitors could require Gentiles to follow the same order of events as Jerusalem.", hook: "The Jewish believers know the Gentiles received the Holy Ghost because they hear them speak with tongues. Peter later explains that event by comparing it directly to Pentecost." },
    { title: "The same gift as at the beginning", reference: "Acts 11:15–17", explanation: "Peter later recalls the Spirit falling on Cornelius's household 'as on us at the beginning.' He argues that God gave them the same gift and that he could not withstand God. The comparison links Gentile reception to Pentecost rather than treating it as a different kind of grace. It strengthens the pattern argument, although Peter's central purpose here is to defend God's acceptance of Gentiles, not to write a systematic list of conversion signs.", hook: "Peter says the Gentiles received the same gift as at the beginning. Acts 19 shows the pattern appearing again in another group of disciples." },
    { title: "The pattern appears again", reference: "Acts 19:6", explanation: "When Paul lays hands on the Ephesian disciples, the Holy Ghost comes on them, and they speak with tongues and prophesy. This supplies another reception narrative outside Jerusalem and Caesarea. It broadens the evidence that tongues can accompany the initial coming of the Spirit. Luke also records prophecy, which cautions readers against ignoring other manifestations in the account. The larger doctrine must draw its conclusions from all the passages together.", hook: "The Ephesian disciples speak with tongues when the Holy Ghost comes upon them. The remaining question is how this reception sign relates to Paul's teaching about the public gift of tongues in the church." },
    { title: "The public gift is distributed", reference: "1 Corinthians 12:30", explanation: "Paul asks whether all speak with tongues while discussing gifts and roles distributed within the gathered church. In that setting, his rhetorical question expects that not everyone exercises every public ministry gift. Apostolic teaching commonly distinguishes this congregational gift from tongues as an initial sign in Acts. That distinction is an interpretation drawn from context, not a phrase Paul states explicitly. A fair study must acknowledge the question and explain the difference rather than skip it.", hook: "First Corinthians discusses distributed ministry gifts in the assembled body, not whether every believer can receive the Spirit in the Acts pattern. From here, the next pathway returns to the gospel itself and the believer's response to Christ's death, burial, and resurrection." }
  ]}),
  pathway({ slug: "gospel-pattern", title: "The Gospel Pattern", summary: "Move from Christ's death, burial, and resurrection into the believer's response.", estimatedMinutes: 10, level: "Foundational", topicSlug: "the-new-birth", collection: "Salvation and new birth", steps: [
    { title: "The gospel events", reference: "1 Corinthians 15:1–4", explanation: "Paul reminds the Corinthians of the gospel they received: Christ died for our sins according to the Scriptures, was buried, and rose on the third day. These are the historical saving events at the heart of Christian proclamation, not merely examples of moral courage. Everything that follows in the apostolic response begins here. Repentance, baptism, and new life have meaning because Jesus truly died, was buried, and was raised from the dead.", hook: "Paul defines the gospel events: Christ died, was buried, and rose again. Luke now shows the response the risen Christ commissions people to make to that gospel." },
    { title: "The risen Christ commissions the response", reference: "Luke 24:46–47", explanation: "The risen Jesus explains that Scripture foretold His suffering and resurrection, then commands that repentance and remission of sins be proclaimed in His name to all nations. The gospel is both an announcement of what Christ has done and a call to respond. That response is grounded in His authority rather than in a separate religious program. Acts shows how the apostles carried this commission into public preaching, beginning at Jerusalem.", hook: "Jesus connects His death and resurrection to repentance and remission preached in His name. Acts 2 gives the apostolic answer when people are convicted by that message." },
    { title: "The apostolic response", reference: "Acts 2:38", explanation: "After declaring Jesus crucified and raised, Peter calls the hearers to repent, be baptized in Jesus Christ's name, and receive the Holy Ghost. His answer applies the gospel to those convicted by it. Apostolic teaching connects repentance with turning from the old life, baptism with identification with Christ, and Spirit reception with new life in God. The verse should be read in the flow of Peter's sermon, where Jesus remains the center.", hook: "Repentance, baptism, and receiving the Holy Ghost answer the gospel proclamation. Romans then shows how baptism corresponds to Christ's death and burial." },
    { title: "Death and burial applied", reference: "Romans 6:3–4", explanation: "Paul says believers baptized into Christ were baptized into His death and buried with Him, so they should walk in newness of life. The language draws a direct connection between baptism and the death, burial, and resurrection of Jesus. It does not reduce baptism to an empty symbol, nor does it portray water as effective apart from Christ. The aim is a changed life shaped by participation in the saving work of the risen Lord.", hook: "Baptism joins believers to Christ's death and burial. Romans 8 completes the pattern by locating resurrection life in the indwelling Spirit." },
    { title: "Resurrection life by the Spirit", reference: "Romans 8:11", explanation: "Paul says that the Spirit of the One who raised Jesus from the dead dwells in believers and that God will give life to their mortal bodies through His indwelling Spirit. Resurrection is not only a fact to remember about Jesus' past; it grounds the believer's present hope and future life. In the surrounding chapter, life in the Spirit also changes how Christians live now. The gospel's goal includes transformation and resurrection hope.", hook: "The gospel is not only an event to affirm but a saving reality believers enter by faith. That prepares the next study question: how grace, faith, and obedient response belong together." }
  ]}),
  pathway({ slug: "faith-grace-and-obedience", title: "Faith, Grace, and Obedience", summary: "Answer the false choice between grace and an obedient response of faith.", estimatedMinutes: 11, level: "Intermediate", topicSlug: "the-new-birth", collection: "Questions and biblical interpretation", steps: [
    { title: "Start with grace", reference: "Ephesians 2:8–10", explanation: "Paul makes the order clear: salvation is by God's grace through faith, not a reward for works that lets anyone boast. Believers are then described as God's workmanship, created in Christ Jesus for good works. Obedience is the fruit and calling of a life God saves, not the price paid to earn that salvation. Read all three verses together, because isolating the warning about works from the following purpose of good works distorts Paul's argument.", hook: "Paul starts with grace: salvation is God's gift, not human boasting. The same passage also says grace creates a people for good works, so Romans asks how faith and obedience relate." },
    { title: "The obedience of faith", reference: "Romans 1:5", explanation: "Paul describes his apostolic calling as bringing about the obedience of faith among the nations for Christ's name. In his language, genuine faith is not mere mental agreement with facts that makes no claim on conduct. Faith receives the gospel and responds to its Lord. This does not turn obedience into a rival source of salvation; it shows the purpose toward which gospel faith moves. Grace begins the response, and the response bears the mark of allegiance to Jesus.", hook: "Paul speaks of the obedience of faith rather than placing obedience against faith. Galatians then describes the kind of faith that matters as faith working through love." },
    { title: "Faith works through love", reference: "Galatians 5:6", explanation: "Paul says that in Christ neither circumcision nor uncircumcision counts for anything, but faith working through love. The contrast is not between faith and every form of action. It is between relying on covenant boundary markers and a living faith expressed in love. A believer cannot point to religious status while neglecting the character Christ calls forth. Paul expects genuine trust in Christ to become visible in how people treat others.", hook: "Biblical faith is active through love. James sharpens the point by naming a faith with no corresponding action as dead." },
    { title: "Dead faith", reference: "James 2:17", explanation: "James says faith without works is dead, then illustrates the claim with a person in need who receives kind words but no practical help. His target is a claim to belief that produces no mercy or obedience. This must be read beside Paul's teaching that salvation is God's gift, not something earned. The authors address different errors: Paul rejects boasting in works, while James rejects a barren profession of faith.", hook: "James rejects a faith that remains only verbal. Colossians then gives baptism as a concrete example of obedient action resting on faith in God's operation." },
    { title: "Baptism through faith", reference: "Colossians 2:12", explanation: "Paul describes believers as buried with Christ in baptism and raised with Him through faith in God's working. The focus is not confidence in a human ritual or in a person's ability to save themselves. It is trust in the God who raised Jesus from the dead. The verse allows baptism and faith to be spoken of together without making the action a wage that purchases grace. God's saving power is the decisive actor throughout.", hook: "Baptism does not compete with grace when the confidence is in God's operation rather than human merit. The next pathway applies the same Scripture-first method to another common question: the right hand of God." }
  ]}),
  pathway({ slug: "right-hand-of-god", title: "The Right Hand of God", summary: "Read right-hand language as power, victory, exaltation, and authority.", estimatedMinutes: 10, level: "Intermediate", topicSlug: "right-hand-of-god", collection: "Questions and biblical interpretation", steps: [
    { title: "Scripture defines the symbol", reference: "Exodus 15:6", explanation: "In the song celebrating deliverance at the sea, Moses speaks of the LORD's right hand as glorious in power and as shattering the enemy. God is not being pictured as needing a second divine ruler seated beside Him to accomplish the victory. The image communicates His effective strength in language people can understand. This Old Testament usage matters before interpreting passages about Christ at God's right hand; biblical imagery must first be read in its own setting.", hook: "Exodus uses God's right hand as language for divine power. Psalm 118 repeats the image so Scripture itself can establish how the symbol functions." },
    { title: "The LORD's right hand acts", reference: "Psalm 118:16", explanation: "The psalm repeats that the right hand of the LORD is exalted and acts valiantly. This is praise for God's victorious power, not a description of a separate god who owns that hand. When Scripture uses right-hand imagery elsewhere, it can communicate authority, victory, honor, and effective rule. Recognizing that range of meaning helps prevent overly literal conclusions. The next step is to see how the Psalms apply this language to the promised Messiah.", hook: "The LORD's right hand acts valiantly, confirming that the phrase describes power and victory. Psalm 110 then applies right-hand language to messianic exaltation." },
    { title: "Messianic exaltation", reference: "Psalm 110:1", explanation: "Psalm 110 opens with the LORD inviting David's lord to sit at His right hand until his enemies are made a footstool. The text is royal and messianic; the exalted figure is given a place of extraordinary honor and rule. The language must not be flattened into merely a poetic phrase, but neither does it automatically settle every question about God's inner being. The New Testament reads the psalm through Jesus' resurrection and exaltation.", hook: "Psalm 110 places the Messiah at the right hand in supreme authority. Peter's Pentecost sermon explains how that prophecy is fulfilled in the risen Jesus." },
    { title: "Peter explains the exaltation", reference: "Acts 2:32–36", explanation: "Peter proclaims that God raised Jesus and exalted Him, then cites Psalm 110 to explain His lordship. The right hand signifies Jesus' enthronement and authority as the risen Messiah. The sermon holds together God's action in raising and exalting Him and Jesus' present exercise of lordship. Apostolic interpreters understand this exaltation without proposing a rival God beside the LORD. The point of Peter's argument is that the crucified Jesus is now both Lord and Christ.", hook: "Peter interprets the right hand through resurrection, exaltation, and authority. First Corinthians then shows where that mediatorial reign is headed." },
    { title: "The kingdom reaches its goal", reference: "1 Corinthians 15:24–28", explanation: "Paul teaches that Christ reigns until every enemy is subdued, including death, and then delivers the kingdom to God the Father. The passage describes a real messianic reign with a purpose and an appointed fulfillment. Its language of subjection and mediation must be taken seriously rather than erased. The final aim is that God may be all in all. A careful reading distinguishes Christ's saving reign from the question of whether there are multiple independent gods.", hook: "Christ's mediatorial reign reaches its saving goal under the one God. The next pathway asks why Jesus prays if full divine presence dwells in Him." }
  ]}),
  pathway({ slug: "jesus-prayers-and-humanity", title: "Jesus' Prayers and Humanity", summary: "Keep Christ's genuine human life and the Father's full indwelling together.", estimatedMinutes: 12, level: "Intermediate", topicSlug: "the-son-of-god", collection: "Questions and biblical interpretation", steps: [
    { title: "Begin with the incarnation", reference: "Luke 1:35", explanation: "Luke explains that the Holy Ghost will come upon Mary and the power of the Highest will overshadow her, so the holy child will be called the Son of God. Jesus' human life begins by God's miraculous initiative, not by ordinary human generation. This provides a starting point for His prayers and obedience: the Son truly enters human history. It does not imply that God's eternal Word began to exist at His birth, a separate question addressed in John 1.", hook: "Luke begins with the incarnation: the Son is the holy child conceived by the Holy Ghost. The next question is whether that humanity is complete enough to include real development." },
    { title: "Real human growth", reference: "Luke 2:52", explanation: "Luke records that Jesus increased in wisdom, stature, and favor with God and people. Genuine growth belongs to human experience, and the Gospel attributes it to Jesus without embarrassment. That matters when reading scenes where He hungers, tires, grieves, or prays. His humanity is not a performance staged for observers. At the same time, the New Testament's claims about His divine identity remain to be considered, not erased by the reality of growth.", hook: "Jesus truly grows in wisdom and stature. John 14 keeps that real humanity together with the equally real indwelling of the Father." },
    { title: "The Father dwelling in Him", reference: "John 14:10", explanation: "Jesus says the Father dwelling in Him performs the works. His human speech and dependence do not lead John to describe the Father as absent from His ministry. Instead, Jesus' visible life is where the Father's presence and action are revealed. This verse helps prevent two opposite mistakes: denying that Jesus was genuinely human or reducing Him to a merely human agent detached from God's presence. Both truths belong in the account of His ministry.", hook: "The Father dwells and works in Christ, so genuine humanity does not require denying deity. Gethsemane then shows that humanity expressing a real human will in submission." },
    { title: "A genuine human will", reference: "Matthew 26:39", explanation: "In Gethsemane, Jesus prays that the cup might pass from Him, yet submits with the words 'not as I will, but as thou wilt.' The agony is real, and the prayer expresses genuine human desire and obedience under suffering. The scene should not be dismissed as a staged conversation. It also does not, by itself, prove the existence of a second independent God. Read it as the incarnate Son's faithful submission in the hour of His sacrifice.", hook: "Jesus' human will submits to the divine will. Hebrews places His prayers, cries, and learned obedience specifically in the days of His flesh." },
    { title: "Prayer in the days of His flesh", reference: "Hebrews 5:7–8", explanation: "Hebrews says Jesus offered prayers and supplications with strong crying and tears in the days of His flesh and learned obedience through what He suffered. The writer is emphasizing the lived reality of His priestly mission. His prayers are not evidence that His humanity was unreal or that suffering was painless. They reveal a Savior who truly entered the conditions of human life and obeyed through them. His saving work includes genuine human faithfulness.", hook: "Hebrews explains prayer within the incarnate life rather than as proof of a second divine being. Colossians closes the study by keeping all divine fullness in the same Christ." },
    { title: "All fullness remains", reference: "Colossians 2:9", explanation: "After considering Jesus' prayers, growth, suffering, and obedience, return to Paul's statement that all the fullness of the Godhead dwells in Christ bodily. The incarnation does not force Scripture to choose between real humanity and full divine presence. Jesus' human experiences should not be used to cancel the high claims about His identity, just as divine fullness should not erase His human life. Together the passages present the mystery of God revealed in the truly human Christ.", hook: "The praying Son remains the bodily dwelling of all the fullness of deity. His genuine humanity and God's full indwelling must be held together rather than used to cancel one another." }
  ]})
];

